mapper.select:
SELECT * FROM score
WHERE 1=1

    AND student_id = #{studentId}


    AND course_id = #{courseId}


    AND semester = #{semester}

ORDER BY create_time DESC

SELECT AVG(total_score) as avgScore, MAX(total_score) as maxScore, MIN(total_score) as minScore, SUM(CASE WHEN total_score >= 60 THEN 1 ELSE 0 END) as passCount, COUNT(*) as totalCount FROM score WHERE 1=1
AND course_id = #{courseId}
AND semester = #{semester}

SELECT CASE WHEN total_score >= 90 THEN '优秀' WHEN total_score >= 80 THEN '良好' WHEN total_score >= 70 THEN '中等' WHEN total_score >= 60 THEN '及格' ELSE '不及格' END as grade, COUNT(*) as count FROM score WHERE 1=1
AND course_id = #{courseId}
AND semester = #{semester}
GROUP BY grade ORDER BY CASE grade WHEN '优秀' THEN 1 WHEN '良好' THEN 2 WHEN '中等' THEN 3 WHEN '及格' THEN 4 WHEN '不及格' THEN 5 END
